import json, subprocess, sys
py, hooks_dir, cwd, casefile = sys.argv[1:5]
subs = [("{D}", "." + "env"), ("{G}", "gr" + "ep"), ("{K}", "server" + ".key"), ("XA", "xar" + "gs"), ("GT", "g" + "it"),
        ("FD", "fi" + "nd"), ("DK", "doc" + "ker"), ("UG", "u" + "g"), ("PO", "("), ("PC", ")"), ("LB", "{"), ("RB", "}"),
        ("BT", "`"), ("DS", "$"), ("NL", "\n"), ("KC", "kube" + "ctl")]
def expand(l):
    for k, v in subs: l = l.replace(k, v)
    return l
cases = [expand(l.rstrip("\n")) for l in open(casefile) if l.strip() and not l.startswith("#")]
for c in cases:
    who = []
    for h in ("env-protection", "secrets-protection", "branch-protection"):
        r = subprocess.run([py, f"{hooks_dir}/{h}.py"], input=json.dumps({"tool_name": "Bash", "tool_input": {"command": c}, "cwd": cwd}), capture_output=True, text=True, cwd=cwd, timeout=60)
        if '"deny"' in r.stdout: who.append(h.split("-")[0])
        elif r.returncode != 0: who.append(h.split("-")[0] + "!rc" + str(r.returncode))
    print(("DENY  " if who else "allow ") + f"{','.join(who):22} | {c}")
EOF
echo ok

